def digest(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest().upper()

def clone(info: zipfile.ZipInfo) -> zipfile.ZipInfo:
    out = zipfile.ZipInfo(info.filename, info.date_time)
    for attr in ("compress_type", "comment", "extra", "create_system",
                 "create_version", "extract_version", "flag_bits", "volume",
                 "internal_attr", "external_attr"):
        setattr(out, attr, getattr(info, attr))
    return out

def main() -> None:
    if digest(BASE.read_bytes()) != BASE_SHA:
        raise SystemExit("base v126 digest differs")
    with zipfile.ZipFile(BASE) as archive:
        infos = archive.infolist()
        members = {i.filename: archive.read(i.filename) for i in infos}

    for name, spans in PATCHES.items():
        data = bytearray(members[name])
        if name == "PSX.EXE":
            if len(data) > PSX_FINAL_SIZE:
                raise SystemExit("PSX.EXE is larger than expected")
            data.extend(bytes(PSX_FINAL_SIZE - len(data)))
        for offset, old_hex, new_hex in spans:
            old = bytes.fromhex(old_hex)
            new = bytes.fromhex(new_hex)
            if bytes(data[offset:offset + len(old)]) != old:
                raise SystemExit(f"{name} 0x{offset:X} base bytes differ")
            data[offset:offset + len(new)] = new
        members[name] = bytes(data)

    with zipfile.ZipFile(OUTPUT, "w", zipfile.ZIP_DEFLATED) as archive:
        for info in infos:
            archive.writestr(clone(info), members[info.filename])

    with zipfile.ZipFile(OUTPUT) as check:
        rebuilt = {i.filename: check.read(i.filename) for i in check.infolist()}
    if rebuilt != members:
        raise SystemExit("ZIP readback differs")
    if digest(OUTPUT.read_bytes()) != OUTPUT_SHA:
        raise SystemExit("output digest differs")
    print(OUTPUT.name)
    print(OUTPUT_SHA)

if __name__ == "__main__":
    main()
